             return AVERROR_PATCHWELCOME;
         }

         avio_rb16(pb);  // data_reference_index.
         if (rb_size(pb, &base_offset, base_offset_size) < 0)
@@ -8758,48 +8759,56 @@ static int mov_read_iloc(MOVContext *c, AVIOContext *pb, MOVAtom atom)
